function indexScene(project){const entries=new Map();const visit=(nodes,parent=null)=>{for(const node of nodes){entries.set(node.id,{node,parent});visit(node.children||[],node.id);}};visit(project.layers);return entries;}
function source(n){if(!['path','freehand'].includes(n?.type))return null;try{const nodes=n.nodes?.some(p=>p.bevelRadius>0)?parsePath(bevelPathData(n)):n.rawPath?parsePath(n.rawPath):n.nodes;return nodes?.length>1?nodes:null;}catch{return null;}}
