function dependencies(entries,id,targetOverride){const entry=entries.get(id);if(!entry)return [];const follow=targetOverride?.id===id?targetOverride.target:entry.node.pathFollow?.enabled?entry.node.pathFollow.targetId:null;return [entry.parent,follow].filter(id=>id&&entries.has(id));}
function cyclic(entries,override){const visiting=new Set(),done=new Set();const visit=id=>{if(visiting.has(id))return true;if(done.has(id))return false;visiting.add(id);for(const other of dependencies(entries,id,override))if(visit(other))return true;visiting.delete(id);done.add(id);return false;};return [...entries.keys()].some(visit);}
export function validatePathFollowReferences(project){const entries=indexScene(project);for(const {node} of entries.values()){if(!node.pathFollow)continue;const f=node.pathFollow;if(!f||typeof f!=='object'||Array.isArray(f)||typeof f.targetId!=='string'||!/^[A-Za-z0-9_-]{1,100}$/.test(f.targetId)||!['enabled','orient','reverse','loop'].every(k=>typeof f[k]==='boolean')||!['originX','originY'].every(k=>Number.isFinite(f[k])))throw Error('Invalid path follow settings.');if(f.targetId===node.id)throw Error('An object cannot follow itself.');const target=entries.get(f.targetId)?.node;if(target&&!pathFollowSupported(target))throw Error('Path follow needs a path or pencil line.');}if(cyclic(entries))throw Error('Path follow would create a circular dependency.');}
function assertTarget(project,id,targetId){const entries=indexScene(project),n=entries.get(id)?.node,target=entries.get(targetId)?.node;if(!n)throw Error('Select an object or group to follow the path.');if(!target)throw Error('Choose an existing path to follow.');if(id===targetId)throw Error('An object cannot follow itself.');if(!pathFollowSupported(target))throw Error('Draw a path or pencil line with at least two points.');if(cyclic(entries,{id,target:targetId}))throw Error('Choose a path outside this character or group; path follow cannot create a circular dependency.');return n;}
export function pathCandidates(project,id){return [...indexScene(project).values()].map(e=>e.node).filter(pathFollowSupported).filter(n=>{try{assertTarget(project,id,n.id);return true;}catch{return false;}});}
