/** Preserve the current displayed pose when a constrained nested object is copied to the root. */
export function rebaseFollowToRoot(project,sourceId,copy,time=0){if(!copy.pathFollow?.enabled)return;const entries=indexScene(project),target=entries.get(copy.pathFollow.targetId)?.node;if(!target)return;const resolved=resolveSceneTransforms(project,time),desired=resolved.get(sourceId)?.world,v=evaluated(copy,time),base=matrix(v),pivot={x:v.anchorX,y:v.anchorY},pose=followPose(pathSamples(evaluated(target,time),resolved.get(target.id).world),pathFollowSettings(v),copy.pathFollow,time);if(!desired||!pose)return;const originalPivot=point(base,pivot),desiredPivot=point(desired,pivot),angle=copy.pathFollow.orient?-pose.angle:0,c=Math.cos(angle),s=Math.sin(angle),a=c*desired[0]-s*desired[1],b=s*desired[0]+c*desired[1],cc=c*desired[2]-s*desired[3],d=s*desired[2]+c*desired[3],rebased=[a,b,cc,d,originalPivot.x-a*pivot.x-cc*pivot.y,originalPivot.y-b*pivot.x-d*pivot.y];copy.prefix=multiply(rebased,inverse(matrix({...v,prefix:undefined})));copy.pathFollow.originX=pose.x+originalPivot.x-desiredPivot.x;copy.pathFollow.originY=pose.y+originalPivot.y-desiredPivot.y;}

const mid=(a,b)=>({x:(a.x+b.x)/2,y:(a.y+b.y)/2});
function flatten(a,b,out,budget,depth=0){const c=a.out||a,d=b.in||b,dx=b.x-a.x,dy=b.y-a.y,length=Math.hypot(dx,dy),poly=Math.hypot(c.x-a.x,c.y-a.y)+Math.hypot(d.x-c.x,d.y-c.y)+Math.hypot(b.x-d.x,b.y-d.y);if(depth>=12||budget.count>=24000||poly-length<.08){out.push({a:{x:a.x,y:a.y},b:{x:b.x,y:b.y}});budget.count++;return;}const ac=mid(a,c),cd=mid(c,d),db=mid(d,b),left=mid(ac,cd),right=mid(cd,db),middle=mid(left,right);flatten({...a,out:ac},{...middle,in:left},out,budget,depth+1);flatten({...middle,out:right},{...b,in:db},out,budget,depth+1);}
/** Flatten in destination coordinates for near-uniform speed after nonuniform scaling. */
export function pathSamples(n,transform=identity()){const nodes=source(n);if(!nodes)return null;const segments=[],budget={count:0};let first,prev;const converted=p=>({...point(transform,p),...(p.in?{in:point(transform,p.in)}:{}),...(p.out?{out:point(transform,p.out)}:{})});for(const node of nodes){const p=converted(node);if(!prev||node.move){first=p;}else flatten(prev,p,segments,budget);if(node.close){flatten(p,first,segments,budget);prev=null;}else prev=p;}if(n.closed&&prev&&first)flatten(prev,first,segments,budget);let length=0;const spans=segments.flatMap(s=>{const distance=Math.hypot(s.b.x-s.a.x,s.b.y-s.a.y);if(distance<1e-8)return [];const start=length;length+=distance;return [{...s,start,end:length,length:distance}];});return length>1e-8?{spans,length}:null;}
export function samplePath(samples,progress){if(!samples)return null;const distance=Math.max(0,Math.min(1,progress))*samples.length;let lo=0,hi=samples.spans.length-1;while(lo<hi){const mid=(lo+hi)>>1;if(samples.spans[mid].end<distance)lo=mid+1;else hi=mid;}const s=samples.spans[lo],u=(distance-s.start)/s.length,dx=(s.b.x-s.a.x)/s.length,dy=(s.b.y-s.a.y)/s.length;return {x:s.a.x+(s.b.x-s.a.x)*u,y:s.a.y+(s.b.y-s.a.y)*u,dx,dy,distance};}
const smooth=t=>t*t*t*(t*(t*6-15)+10);
const lattice=(x,y,seed)=>{const value=Math.sin(x*127.1+y*311.7+seed*74.7)*43758.5453123;return 2*(value-Math.floor(value))-1;};
function coherentNoise(x,y,seed){const ix=Math.floor(x),iy=Math.floor(y),u=smooth(x-ix),v=smooth(y-iy),mix=(a,b,t)=>a+(b-a)*t;return mix(mix(lattice(ix,iy,seed),lattice(ix+1,iy,seed),u),mix(lattice(ix,iy+1,seed),lattice(ix+1,iy+1,seed),u),v);}
function followPose(samples,settings,follow,time){let progress=settings.followProgress/100;progress=follow.loop?((progress%1)+1)%1:Math.max(0,Math.min(1,progress));if(follow.reverse)progress=1-progress;const p=samplePath(samples,progress);if(!p)return null;const x=p.distance/settings.followNoiseSize,y=time*settings.followNoiseSpeed,noise=settings.followNoiseAmount*(.75*coherentNoise(x,y,settings.followNoiseSeed)+.25*coherentNoise(x*2+17,y*2+29,settings.followNoiseSeed+101)),offset=settings.followOffset+noise;return {...p,x:p.x-p.dy*offset,y:p.y+p.dx*offset,angle:Math.atan2(p.dy,p.dx)+(follow.reverse?Math.PI:0)};}
/** One pure constraint pass shared by export, preview, hit testing and selection. */
export function resolveSceneTransforms(project,time=0,preview){const entries=indexScene(project),resolved=new Map(),visiting=new Set(),sampleCache=new Map();const visit=id=>{if(resolved.has(id))return resolved.get(id);const entry=entries.get(id);if(!entry)return {local:identity(),world:identity()};const {node,parent}=entry,v={...evaluated(node,time),...(preview?.get(id)||{})};let local=matrix(v);if(visiting.has(id))return {local,world:local};visiting.add(id);const parentWorld=parent?visit(parent).world:identity(),follow=v.pathFollow;if(follow?.enabled&&entries.has(follow.targetId)&&!visiting.has(follow.targetId)){try{const target=entries.get(follow.targetId).node,targetValue={...evaluated(target,time),...(preview?.get(target.id)||{})},targetMatrix=multiply(inverse(parentWorld),visit(target.id).world),cacheKey=target.id+':'+(parent||''),samples=sampleCache.has(cacheKey)?sampleCache.get(cacheKey):pathSamples(targetValue,targetMatrix),pose=followPose(samples,pathFollowSettings(v),follow,time);sampleCache.set(cacheKey,samples);if(pose){const pivot={x:v.anchorX,y:v.anchorY},original=point(local,pivot),angle=follow.orient?pose.angle:0,c=Math.cos(angle),s=Math.sin(angle),a=c*local[0]-s*local[1],b=s*local[0]+c*local[1],cc=c*local[2]-s*local[3],d=s*local[2]+c*local[3],x=pose.x+original.x-follow.originX,y=pose.y+original.y-follow.originY;local=[a,b,cc,d,x-a*pivot.x-cc*pivot.y,y-b*pivot.x-d*pivot.y];}}catch{/* A deleted/degenerate path or zero-scale parent leaves editable base artwork. */}}const result={local,world:multiply(parentWorld,local)};resolved.set(id,result);visiting.delete(id);return result;};for(const id of entries.keys())visit(id);return resolved;}
/** A fresh frame-local cache also resolves temporal blur and onion-skin samples. */
export function pathTransformContext(project,preview){if(![...indexScene(project).values()].some(({node})=>node.pathFollow?.enabled))return {};const cache=new Map();return {transformAt(id,time){if(!cache.has(time))cache.set(time,resolveSceneTransforms(project,time,preview));return cache.get(time).get(id)?.local;}};}
